(async () => {
  const game = window.DRIFTWING;
  const ctx = game.ctx;
  const spawns = ctx.systems.spawns;
  if (!spawns.debug) throw new Error('the preset steps need the spawns dev API (a dev server, or a build with ?dev=1)');
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const manager = spawns.manager;
  const pb = {
    ctx, spawns, manager, sleep,
    frame: () => new Promise((resolve) => requestAnimationFrame(resolve)),
    check(name, ok, detail) {
      if (!ok) console.error(`[preset check] ${name} failed: ${detail}`);
      return `${ok ? 'PASS' : 'FAIL'} ${name}: ${detail}`;
    },
    memory() {
      const memory = ctx.renderer.info.memory;
      return { geometries: memory.geometries, textures: memory.textures };
    },
    sun(elevation) { ctx.systems.sky.setDayTime(ctx.util.dayTimeForSunElevation(elevation, true), { transition: 0 }); },
    at(x, z) { return { x, y: Math.max(ctx.world.groundHeight(x, z), ctx.world.WATER_LEVEL), z }; },
    endDebug() { for (const spawn of manager.getActive()) if (spawn.source === 'debug') manager.deactivate(spawn.id, 'test'); },
    /** A camera spot dist metres from pt with the clearest sight line to pt.y + lift (best of 24 bearings). */
    spot(pt, dist, lift, height) {
      const world = ctx.world;
      let best = null;
      for (let angle = 0; angle < 360; angle += 15) {
        const radians = angle * Math.PI / 180;
        const x = pt.x + Math.sin(radians) * dist;
        const z = pt.z - Math.cos(radians) * dist;
        const y = Math.max(world.groundHeight(x, z), world.WATER_LEVEL) + height;
        const targetY = pt.y + lift * 0.3;
        let block = 0;
        for (let step = 1; step < 30; step++) {
          const t = step / 30;
          block = Math.max(block, world.groundHeight(x + (pt.x - x) * t, z + (pt.z - z) * t) - (y + (targetY - y) * t));
        }
        const score = block + Math.abs(y - pt.y) * 0.05;
        if (!best || score < best.score) best = { score, x, y, z };
      }
      return best;
    },
    /** The craft flies at a spot facing pt (so the chase camera looks at it). */
    async approach(pt, dist, height, seconds = 1.5) {
      ctx.setPhotoMode(false);
      const spot = pb.spot(pt, dist, 0, height);
      ctx.systems.flight.resetTo({ x: spot.x, y: spot.y, z: spot.z, heading: ctx.util.bearingTo(spot.x, spot.z, pt.x, pt.z) });
      await sleep(seconds * 1000);
      return spot;
    },
    /** Photo mode, the free camera at cam looking at target (the craft parks beside the camera first). */
    async frameShot(cam, target, fov = 60) {
      ctx.setPhotoMode(false);
      ctx.systems.flight.resetTo({ x: cam.x, y: cam.y + 60, z: cam.z, heading: ctx.util.bearingTo(cam.x, cam.z, target.x, target.z) });
      await sleep(2500);
      ctx.setPhotoMode(true);
      await sleep(300);
      ctx.systems.camera.setFreeCameraPose({ position: cam, target, fov });
      await sleep(1800);
    },
    async shotAt(pt, dist, lift, height, fov = 60) {
      const spot = pb.spot(pt, dist, lift, height);
      await pb.frameShot({ x: spot.x, y: spot.y, z: spot.z }, { x: pt.x, y: pt.y + lift, z: pt.z }, fov);
    },
    /** Waits until the spawn is discovered, keeping the craft facing it; returns the seconds waited. */
    async discovered(id, pt, dist, height) {
      for (let tick = 0; tick < 40; tick++) {
        const info = manager.getInstance(id);
        if (info && info.discovered) return tick * 0.5;
        if (tick % 6 === 0) await pb.approach(pt, dist, height, 0.2);
        await sleep(500);
      }
      return -1;
    },
    /** The discovery card's text once it shows name (cards queue behind each other: up to 12 s). */
    async card(name) {
      for (let tick = 0; tick < 48; tick++) {
        const found = window.__pbCards.find((text) => text.includes(name));
        if (found) return found;
        await sleep(250);
      }
      return '';
    },
    journalHas(key) { return ctx.systems.journal.getData().spawnsFound.some((entry) => entry.id === key); },
  };
  window.__pb = pb;
  window.__pbCards = [];
  const record = () => { const card = document.querySelector('.dw-discovery'); if (card && card.textContent && !window.__pbCards.includes(card.textContent)) window.__pbCards.push(card.textContent); };
  new MutationObserver(record).observe(document.body, { subtree: true, childList: true, characterData: true });
  window.__pbStats = [];
  ctx.bus.onTyped('journalStat', (event) => window.__pbStats.push(event));
  ctx.settings.set('timeFrozen', true);
  const presets = manager.listPresets().map((preset) => preset.id);
  const wanted = ['tornado', 'supercell', 'waterspout', 'lenticular', 'microburst', 'glory', 'volcano', 'geyserField', 'slotCanyon', 'megaWaterfall'];
  return pb.check('presets 1-10 are registered in spec order', wanted.every((id, index) => presets[index] === id), presets.join(', '));
})()

