(async () => {
    // A clean run: in through the entry, down the canyon (carried in 30 m steps, 35 m over the floor),
    // out through the exit; then a run that climbs out above the rim in the middle.
    const pb = window.__pb; const ctx = pb.ctx; const site = window.__pbSite.site; const path = site.stamps[0].path; const last = path.length - 1;
    const events = { course: [], gates: [], stats: [] };
    ctx.bus.on('structure:course', (event) => events.course.push(event));
    ctx.bus.on('structure:gate', (event) => events.gates.push(event.gate));
    const statsBefore = window.__pbStats.length;
    const heading = (a, b) => (Math.atan2(b.x - a.x, -(b.z - a.z)) * 180 / Math.PI + 360) % 360;
    const place = async (x, z, floor, toward) => { ctx.systems.flight.resetTo({ x, y: Math.max(floor, ctx.world.groundHeight(x, z)) + 35, z, heading: toward }); await pb.frame(); await pb.frame(); };
    const carry = async (from, to, climb = null) => {
      for (let index = from; index < to; index++) {
        const a = path[index];
        const b = path[index + 1];
        const length = Math.hypot(b.x - a.x, b.z - a.z);
        for (let along = 0; along < length; along += 30) {
          const x = a.x + (b.x - a.x) * along / length;
          const z = a.z + (b.z - a.z) * along / length;
          const lift = climb && index >= climb ? 150 : 0;
          ctx.systems.flight.resetTo({ x, y: Math.max(a.floorY, ctx.world.groundHeight(x, z)) + 35 + lift, z, heading: heading(a, b) });
          await pb.frame();
          await pb.frame();
        }
      }
    };
    const outside = { x: 2 * path[0].x - path[1].x, z: 2 * path[0].z - path[1].z };
    const run = async (climb) => {
      const length = Math.hypot(path[0].x - outside.x, path[0].z - outside.z);
      await place(path[0].x + (outside.x - path[0].x) * 60 / length, path[0].z + (outside.z - path[0].z) * 60 / length, path[0].floorY, heading(outside, path[0]));
      for (let step = 0; step < 6; step++) await place(path[0].x + (outside.x - path[0].x) * (60 - step * 20) / length, path[0].z + (outside.z - path[0].z) * (60 - step * 20) / length, path[0].floorY, heading(outside, path[0]));
      await carry(0, last, climb);
      const end = path[last];
      for (let step = 0; step < 6; step++) await place(end.x + (end.x - path[last - 1].x) * step * 0.05, end.z + (end.z - path[last - 1].z) * step * 0.05, end.floorY, heading(path[last - 1], end));
      await pb.sleep(500);
    };
    await run(null);
    const clean = { courses: events.course.length, clean: events.course.length > 0 && events.course[0].clean, stats: window.__pbStats.slice(statsBefore).filter((event) => event.key === 'bestCanyonRun') };
    events.course.length = 0;
    await run(Math.floor(last / 2));
    const records = ctx.systems.journal.getData().records;
    return [
      pb.check('slotCanyon: entry and exit are detected and a clean run is timed', clean.courses === 1 && clean.clean && events.gates.includes('start') && events.gates.includes('finish'), JSON.stringify(clean)),
      pb.check('slotCanyon: the clean run reaches the journal as bestCanyonRun (op min)', clean.stats.length === 1 && clean.stats[0].op === 'min' && records.stats.bestCanyonRun && records.stats.bestCanyonRun.value === clean.stats[0].value, JSON.stringify(records.stats.bestCanyonRun)),
      pb.check('slotCanyon: a run that climbs out above the rim is not clean', events.course.length === 0, String(events.course.length)),
    ].join(' | ');
  })()

